<template>
  <el-form label-position="top" :disabled="disabled" aria-label="排班原来源草稿字段" @submit.prevent>
    <p>请按原记录填写资质、可用时间和班次。证照、个人原因和审核依据保存在院内。</p>
    <el-form-item v-for="field in fields" :key="field.key" :label="field.label"><el-select v-if="field.values" v-model="draft[field.key]" :aria-label="field.label" placeholder="请明确选择"><el-option v-for="entry in field.values" :key="String(entry[0])" :label="entry[1]" :value="entry[0]" /></el-select><el-input v-else v-model="draft[field.key]" :aria-label="field.label" :type="field.key==='authorized_job_keys'?'textarea':'text'" :placeholder="field.key==='authorized_job_keys'?'按原定义填写岗位代码，每行一个；不从职称生成':field.key==='policy_reference'?'实际审核规则或原文标识':'YYYY-MM-DDTHH:mm:ss.ffffffZ，明确UTC或偏移'" :maxlength="field.key==='policy_reference'?2000:field.key==='authorized_job_keys'?10000:100" /></el-form-item>
    <nullable-value v-if="kind==='duty_interval'" v-model="job" kind="job" label="班次原岗位标识" />
    <nullable-value v-if="kind==='work_rule_policy'" v-model="policyEnd" kind="clock" label="规则原有效结束UTC" />
    <template v-if="kind==='work_rule_policy'"><p>以下均为本次有原依据的运营约束，单位为分钟。滚动24小时/7日与固定窗口分别保留，不自动填写法定或院内默认时长。</p><nullable-value v-for="key in rosterPolicyConstraints" :key="key" :model-value="constraints[key]||{}" :label="constraintLabels[key]" @update:model-value="constraints[key]=$event" /><el-button :disabled="windows.length>=64" @click="windows.push({minimum:{},maximum:{}})">添加原固定工时窗口</el-button><p>共 {{ windows.length }} 个固定窗口，最多64个；分页不省略任何窗口。</p><article v-for="(row,index) in visibleWindows" :key="windowStart+index" :aria-label="`原固定工时窗口${windowStart+index+1}`"><el-form-item label="固定工时窗口开始UTC"><el-input v-model="row.start_at" aria-label="固定工时窗口开始UTC" /></el-form-item><el-form-item label="固定工时窗口结束UTC"><el-input v-model="row.end_at" aria-label="固定工时窗口结束UTC" /></el-form-item><nullable-value v-model="row.minimum" label="固定窗口最少工作分钟" /><nullable-value v-model="row.maximum" label="固定窗口最多工作分钟" /><el-button @click="windows.splice(windowStart+index,1)">移除此未提交窗口</el-button></article><el-pagination v-if="windows.length>20" v-model:current-page="windowPage" :page-size="20" :total="windows.length" layout="prev,pager,next" /></template>
    <breaks-editor v-if="kind==='duty_interval'" v-model="breaks" :disabled="disabled" />
    <el-form-item label="排班原来源核实依据"><el-input v-model="draft.evidence_basis_note" aria-label="排班原来源核实依据" type="textarea" maxlength="4000" placeholder="至少20个非空白字符，记录真实原核实依据；正文仅院内保存" /></el-form-item>
    <p v-if="!valid">请完整填写原字段、明确未知原因和实际依据；未选状态不会自动确认。</p>
  </el-form>
</template>
<script setup>
import {computed,ref,watch} from "vue";
import {rosterPayloadValid,rosterPolicyConstraints} from "@/api/rosterSources";
import {supportUtc} from "@/api/inpatientSupport";
import NullableValue from "./NullableValue.vue";
import BreaksEditor from "./BreaksEditor.vue";
const props=defineProps({kind:{type:String,required:true},disabled:{type:Boolean,default:false}}),emit=defineEmits(['validity']);
const draft=ref({}),job=ref({}),policyEnd=ref({}),constraints=ref({}),breaks=ref([]),windows=ref([]),windowPage=ref(1);
const states={employment_status:[['active','原在岗状态有效'],['inactive','原在岗状态无效'],['unknown','原在岗状态未知']],qualification_status:[['verified','原资格已明确核验'],['not_verified','原资格未核验'],['unknown','原资格未知']],expiry_status:[['known','原到期时刻明确'],['unknown','原到期未知'],['not_applicable','明确无适用到期（需原依据）']],commitment_status:[['committed','已明确计划承诺'],['completed','实际已经完成'],['cancelled','原班次已取消'],['unknown','原承诺状态未知']],work_location:[['home_department','原本科室'],['other_department','原其他科室'],['external','院外实际工作'],['unknown','原地点未知']],breaks_complete:[[true,'明确已核全全部休息（true）'],[false,'未核全休息记录（false）']],time_accounting_status:[['verified','原时间核算已核实'],['unknown','原时间核算未知']],availability:[['available','明确可用'],['unavailable','明确不可用'],['unknown','原可用性未知']],basis_kind:[['staff_declaration','人员原声明'],['approved_leave','实际已批请假'],['administrative_confirmation','原行政核实'],['other','其他原依据']]};
const labels={employment_status:'原在岗状态',qualification_status:'原资格核验状态',authorized_job_keys:'原授权岗位代码',valid_from_at:'资格原有效开始UTC',valid_until_at:'资格原到期UTC',expiry_status:'资格原到期状态',start_at:'原区间开始UTC',end_at:'原区间结束UTC',commitment_status:'原班次承诺状态',work_location:'原班次工作地点',breaks_complete:'原休息记录完整核实',time_accounting_status:'原时间核算状态',availability:'原可用性状态',basis_kind:'原可用性依据类型',effective_from_at:'规则原有效开始UTC',policy_reference:'工时规则原依据标识'};
const constraintLabels={max_single_duty_presence_minutes:'单次在岗最长分钟',max_work_minutes_rolling_24h:'滚动24小时最多工作分钟',max_work_minutes_rolling_7d:'滚动7日最多工作分钟',minimum_rest_minutes:'相邻班次至少休息分钟'};
const fields=computed(()=>({qualification:['employment_status','qualification_status','authorized_job_keys','valid_from_at','expiry_status',...(draft.value.expiry_status==='known'?['valid_until_at']:[])],duty_interval:['start_at','end_at','commitment_status','work_location','breaks_complete','time_accounting_status'],availability:['start_at','end_at','availability','basis_kind'],work_rule_policy:['effective_from_at','policy_reference']}[props.kind]||[]).map(key=>({key,label:labels[key],values:states[key]})));
const windowStart=computed(()=>(windowPage.value-1)*20),visibleWindows=computed(()=>windows.value.slice(windowStart.value,windowStart.value+20));
function value(row,type='count'){if(['unknown','not_applicable'].includes(row?.state))return{value:null,absent_reason:row.state};if(type==='boolean'&&['true','false'].includes(row?.state))return{value:row.state==='true',absent_reason:null};if(row?.state!=='known')throw new Error('请明确选择原值或未知原因');const text=String(row.value??'');return{value:type==='clock'?supportUtc(text):type==='job'?text.trim():/^(?:0|[1-9]\d*)$/.test(text)?Number(text):undefined,absent_reason:null};}
function build(){const d=draft.value,basis={evidence_basis_note:d.evidence_basis_note};if(props.kind==='qualification')return{...basis,employment_status:d.employment_status,qualification_status:d.qualification_status,authorized_job_keys:String(d.authorized_job_keys||'').split(/[\n,]/).map(v=>v.trim()).filter(Boolean),valid_from_at:supportUtc(d.valid_from_at),valid_until_at:d.expiry_status==='known'?supportUtc(d.valid_until_at):null,expiry_status:d.expiry_status};if(props.kind==='availability')return{...basis,start_at:supportUtc(d.start_at),end_at:supportUtc(d.end_at),availability:d.availability,basis_kind:d.basis_kind};if(props.kind==='duty_interval'){const j=value(job.value,'job');return{...basis,start_at:supportUtc(d.start_at),end_at:supportUtc(d.end_at),commitment_status:d.commitment_status,work_location:d.work_location,job_key:j.value,job_key_absent_reason:j.absent_reason,breaks:breaks.value.map(row=>{const a=value(row.accounting,'boolean');return{start_at:supportUtc(row.start_at),end_at:supportUtc(row.end_at),counted_as_work:a.value,counted_as_work_absent_reason:a.absent_reason};}),breaks_complete:d.breaks_complete,time_accounting_status:d.time_accounting_status};}const end=value(policyEnd.value,'clock');return{...basis,effective_from_at:supportUtc(d.effective_from_at),effective_until_at:end.value,effective_until_absent_reason:end.absent_reason,...Object.fromEntries(rosterPolicyConstraints.map(key=>[key,value(constraints.value[key])])),fixed_work_windows:windows.value.map(row=>({start_at:supportUtc(row.start_at),end_at:supportUtc(row.end_at),minimum_work_minutes:value(row.minimum),maximum_work_minutes:value(row.maximum)})),policy_reference:d.policy_reference};}
watch(()=>windows.value.length,length=>{windowPage.value=Math.min(windowPage.value,Math.max(1,Math.ceil(length/20)));});
const valid=computed(()=>{try{return rosterPayloadValid(props.kind,build());}catch{return false;}});watch(valid,value=>emit('validity',value),{immediate:true});defineExpose({build});
</script>
<style scoped>p{line-height:1.7}article{border:1px solid #ddd;padding:12px;margin:8px 0}.el-button{margin:8px 8px 8px 0}</style>
